l{display:flex;justify-content:space-between;margin-bottom:5px}.xp-label b{font-weight:400;color:#eed5e0}.xp-track{height:3px;background:#352b42;border-radius:4px;overflow:hidden}.xp-track i{height:100%;display:block;background:linear-gradient(90deg,#bd8dff,#ffc2d1);width:0;box-shadow:0 0 9px #ce9efc;transition:width .25s}.objective{position:absolute;z-index:2;left:50%;bottom:54px;transform:translateX(-50%);display:flex;align-items:center;gap:11px;white-space:nowrap;color:#c8bbcc;font:10px 'DM Mono';letter-spacing:.25px;background:#181323a8;border:1px solid #e1c4db24;padding:10px 14px;border-radius:3px;transition:opacity .3s}.obj-icon{color:#ef9cbd;font-size:15px}.objective kbd{font:8px 'DM Mono';color:#e2cedf;border:1px solid #ddc9dc47;border-radius:3px;padding:3px 5px;margin-left:2px}.toast{position:absolute;top:160px;left:50%;transform:translate(-50%,-10px);z-index:4;font:10px 'DM Mono';letter-spacing:2px;color:#ffe4ee;text-shadow:0 0 18px #e58ba8;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}footer{position:absolute;z-index:2;bottom:22px;left:5.2%;right:5.2%;display:flex;justify-content:space-between;color:#b3a5b7;font:8px 'DM Mono';letter-spacing:1.1px;pointer-events:none}footer b{font:700 8px 'Outfit';letter-spacing:1.5px;color:#ebdce4}footer i{font-style:normal;color:#a396ad;font-size:7px}footer span:last-child{color:#988da2}footer span:last-child b{color:#e19cb7;margin-left:7px}.screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:rgba(15,11,26,.34);opacity:0;visibility:hidden;transition:opacity .35s,visibility .35s}.screen.visible{opacity:1;visibility:visible}.screen-backdrop{position:absolute;inset:0;background:linear-gradient(90deg,rgba(15,11,27,.88) 0%,rgba(15,11,27,.76) 44%,rgba(15,11,27,.12) 100%),linear-gradient(0deg,#100d20b0,transparent 35%,#100d2040)}.title-wrap{position:absolute;left:10.8%;top:50%;transform:translateY(-48%);z-index:2;width:min