t 3s ease-in-out infinite}.s1{top:29%;left:20%;font-size:22px}.s2{top:67%;right:17%;font-size:18px;animation-delay:-1s}.s3{top:17%;right:24%;font-size:13px;animation-delay:-2s}@keyframes float{50%{transform:translateY(-9px) rotate(15deg);opacity:.55}}.version{position:absolute;right:5%;bottom:22px;color:#a092a8;font:8px 'DM Mono';letter-spacing:1px;z-index:2}.version span{color:#dd9ab5;margin:0 7px}.modal-card{position:relative;width:min(520px,90vw);padding:40px 42px;text-align:center;background:linear-gradient(145deg,rgba(37,27,48,.96),rgba(22,18,34,.97));border:1px solid #ddb5d335;box-shadow:0 22px 100px #090612b8,0 0 0 5px #d6a5ca08;backdrop-filter:blur(14px)}.modal-card:before,.modal-card:after{content:'✦';position:absolute;color:#d794b3;font-size:12px;top:13px;left:15px}.modal-card:after{left:auto;right:15px}.modal-eyebrow{font-size:8px;color:#d6a6bc}.modal-card h2{font:600 45px/1 'Cormorant Garamond';letter-spacing:3px;color:#f5e5e4;margin:13px 0 10px}.modal-card h2 em{font-style:normal;color:#eea0bb}.modal-card h2 span{color:#eea0bb}.modal-copy{font-size:12px;color:#c1b2c4;margin:0 0 22px}.level-modal{width:min(650px,92vw)}.upgrade-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:23px 0 15px}.upgrade-card{background:linear-gradient(140deg,#31253b,#211b2c);border:1px solid #cf9fbd40;padding:15px 11px 14px;text-align:left;cursor:pointer;min-height:139px;transition:.2s;position:relative}.upgrade-card:hover{border-color:#ecacc8;transform:translateY(-3px);background:#38263b}.upgrade-card .upgrade-icon{font-size:22px;color:#f2a9c3;margin-bottom:10px}.upgrade-card strong{display:block;font-size:11px;letter-spacing:.4px;color:#f2e3e5;margin-bottom:5px}.upgrade-card p{font-size:9px;line-height:1.5;color:#b8aabe;margin:0}.choose-hint{font:8px 'DM Mono';letter-spacing:1.7px;color:#a894ab}.pause-modal,.end-modal{width:min(450px,90vw)}.pause-modal .primary-btn,.end-modal .primary-btn{margin:24px auto 0}.pause-foot{font:8px 'DM Mono';letter-spacing:1px;color:#a99bae;margin-top:22px}.pause-foot i{color:#d993b2;font-style:normal;margin:0 5px}.run-stats{display:flex;justify-content:space-around;border-top:1px solid #dcb4d328;border-bottom:1px solid #dcb4d328;padding:15px 0;margin-top:22px}.run-stats div{display:flex;flex-direction:column;gap:4px}.run-stats b{font:21px 'Cormorant Garamond';color:#f2dce6}.run-stats small{font:7px 'DM Mono';letter-spacing:1px;color:#aa9bb1}.touch-controls{display:none;position:absolute;z-index:3;inset:auto 0 42px;justify-content:space-between;padding:0 28px;pointer-events:none}.dpad,.dash-wrap{pointer-events:auto}.dpad>button,.dpad div button{background:#211c30a8;border:1px solid #e3c4dc4a;width:39px;height:39px;border-radius:50%;color:#e4cddd;font-size:12px;touch-action:none}.dpad>button{display:block;margin:auto auto 3px}.dpad div{display:flex;gap:4px}.dpad div button:nth-child(2){margin-top:42px}.dash-wrap{display:flex;align-items:flex-end}.dash-wrap button{width:51px;height:51px;border-radius:50%;border:1px solid #e9a6c4;background:#803d64aa;color:#ffe5ef;font-size:19px;box-shadow:0 0 20px #de83ae42;touch-action:none}.dash-wrap small{display:block;font:6px 'DM Mono';letter-spacing:1px}.playing .objective{opacity:.85}
