(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const screens = ['startScreen','levelScreen','pauseScreen','gameOverScreen'];
  const ui = {level:$('level'), hp:$('hpText'), health:$('healthFill'), timer:$('timer'), kills:$('kills'), xp:$('xp'), xpNeed:$('xpNeed'), xpFill:$('xpFill'), toast:$('toast')};
  let W=innerWidth,H=innerHeight,DPR=1, mode='title', last=0, time=0, spawnClock=0, attackClock=0, kills=0, level=1, xp=0, xpNeed=8, shake=0, toastClock=0, soundOn=false;
  let player, enemies=[], shots=[], gems=[], particles=[], slash=[], keys={}, touch={}, buildings=[], trees=[], elapsed=0, dashCooldown=0, bossSpawned=false;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0);seedDecor();}
  function seedDecor(){buildings=[];trees=[];for(let i=0;i<48;i++){buildings.push({x:rand(-2300,2300),y:rand(-2300,2300),w:rand(65,150),h:rand(70,170),seed:Math.random()});trees.push({x:rand(-2400,2400),y:rand(-2400,2400),s:rand(.6,1.3)});}}
  function fresh(){player={x:0,y:0,hp:100,maxHp:100,speed:210,damage:24,fireRate:.85,range:470,blades:1,invuln:0,dx:1,dy:0,trail:[],dash:0};enemies=[];shots=[];gems=[];particles=[];slash=[];time=0;elapsed=0;spawnClock=.5;attackClock=.8;kills=0;level=1;xp=0;xpNeed=8;dashCooldown=0;bossSpawned=false;shake=0;ui.toast.classList.remove('show');updateHud();}
  function setScreen(id){screens.forEach(s=>$(s).classList.toggle('visible',s===id));}
  function start(){fresh();mode='play';setScreen('');document.body.classList.add('playing');last=performance.now();}
  function pause(){if(mode!=='play')return;mode='pause';setScreen('pauseScreen');}
  function resume(){if(mode!=='pause')return;mode='play';setScreen('');last=performance.now();}
  function endGame(won=false){mode='end';setScreen('gameOverScreen');$('endEyebrow').textContent=won?'THE FIRST LIGHT RETURNS':'THE NIGHT CLAIMS ANOTHER';$('endTitle').innerHTML=won?'DAWN<span>.</span>':'FALLEN<span>.</span>';$('endCopy').textContent=won?'You held the line until the sun came up. The city will remember.':'The moon remembers your name. Rise again, blade of the dusk.';$('finalTime').textContent=formatTime(time);$('finalKills').textContent=kills;$('finalLevel').textContent=level;}
  function formatTime(t){let n=Math.floor(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
  function updateHud(){ui.level.textContent=String(level).padStart(2,'0');ui.hp.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.health.style.width=`${100*player.hp/player.maxHp}%`;ui.timer.textContent=formatTime(time);ui.kills.textContent=String(kills).padStart(3,'0');ui.xp.textContent=xp;ui.xpNeed.textContent=xpNeed;ui.xpFill.style.width=`${100*xp/xpNeed}%`;}
  function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastClock=1.5;}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(35,180);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.65),max:.65,color,size:rand(1,3.5)});}}
  function makeEnemy(){let a=rand(0,Math.PI*2),r=Math.max(W,H)*.65+rand(45,180),x=player.x+Math.cos(a)*r,y=player.y+Math.sin(a)*r;let boss=time>120&&!bossSpawned&&Math.random()<.14;if(boss)bossSpawned=true;let type=boss?'boss':(Math.random()<.26?'wraith':'shade');enemies.push({x,y,type,hp:boss?300:Math.round(35+time*.28),maxHp:boss?300:Math.round(35+time*.28),speed:boss?39:(type==='wraith'?74:52)+Math.min(time*.15,22),damage:boss?22:10,rad:boss?25:(type==='wraith'?13:16),phase:rand(0,7),attack:0});if(boss)notify('A CATHEDRAL WARDEN APPROACHES');}
  function nearest(){let target=null,d=Infinity;for(const e of enemies){let dd=(e.x-player.x)**2+(e.y-player.y)**2;if(dd<d){d=dd;target=e;}}return target;}
  function shoot(){let target=nearest();if(!target)return;let a=Math.atan2(target.y-player.y,target.x-player.x),count=player.blades;for(let i=0;i<count;i++){let angle=a+(i-(count-1)/2)*.22;shots.push({x:player.x+Math.cos(angle)*15,y:player.y+Math.sin(angle)*15,vx:Math.cos(angle)*480,vy:Math.sin(angle)*480,damage:player.damage,life:1.15,trail:[]});}slash.push({x:player.x,y:player.y,a,life:.27,max:.27});}
  function gainXp(n){xp+=n;if(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.round(xpNeed*1.35+3);updateHud();openUpgrade();}updateHud();}
  const upgrades=[{icon:'✧',name:'MOONLIT EDGE',desc:'Your blade hits 35% harder.',apply:()=>player.damage*=1.35},{icon:'❀',name:'GHOSTSTEP',desc:'Move 18% faster through the dark.',apply:()=>player.speed*=1.18},{icon:'♡',name:'BLOOD ORCHID',desc:'Restore 35 vitality to your heart.',apply:()=>player.hp=Math.min(player.maxHp,player.hp+35)},{icon:'☄',name:'TWIN COMET',desc:'Send an additional blade each volley.',apply:()=>player.blades=Math.min(5,player.blades+1)},{icon:'⟡',name:'QUICKENING',desc:'Attack 22% more frequently.',apply:()=>player.fireRate*=.78},{icon:'◈',name:'SILVER THREAD',desc:'Pull moonshards from further away.',apply:()=>player.range+=100}];
